-- =====================================================
-- Consecutivo por area para las 7 denuncias del Excel
-- (antes quedaban como SDPIS-2026-90xx). Se usa el mismo
-- contador que sp_registrar_denuncia, asi las que se registren
-- despues (script 16, formulario) siguen la numeracion sin chocar.
-- Se reparten entre las 4 areas de prueba.
-- =====================================================
DECLARE
  v_area_id area.id_area%TYPE;
  v_anio    NUMBER(4);
  v_numero  NUMBER;
BEGIN
  FOR r IN (
    SELECT d.id_denuncia, d.fecha_creacion,
           CASE d.id_denuncia
             WHEN 9004 THEN 'ACOS'
             WHEN 9005 THEN 'LIMO'
             WHEN 9006 THEN 'SRAM'
             WHEN 9007 THEN 'LIMO'
             ELSE 'ABAN'
           END AS codigo_area
      FROM denuncia d
     WHERE d.id_denuncia BETWEEN 9001 AND 9007
     ORDER BY d.id_denuncia
  ) LOOP
    SELECT id_area INTO v_area_id FROM area WHERE codigo_area = r.codigo_area;
    v_anio := EXTRACT(YEAR FROM r.fecha_creacion);

    UPDATE contador_denuncia_area
       SET ultimo_numero = ultimo_numero + 1
     WHERE area_id = v_area_id AND anio = v_anio
    RETURNING ultimo_numero INTO v_numero;

    IF SQL%ROWCOUNT = 0 THEN
      INSERT INTO contador_denuncia_area (area_id, anio, ultimo_numero)
      VALUES (v_area_id, v_anio, 1);
      v_numero := 1;
    END IF;

    UPDATE denuncia
       SET area_actual_id    = v_area_id,
           numero_secuencial = v_numero,
           consecutivo       = r.codigo_area || '-' || v_anio || '-' || LPAD(v_numero, 6, '0')
     WHERE id_denuncia = r.id_denuncia;
  END LOOP;
  COMMIT;
END;
/


