-- #####################################################################
-- HU-008: denuncias que prueban la asignacion de area por ubicacion
-- Origen: 16_prueba_hu008_asignacion_areas.sql (seccion 3)
-- #####################################################################
-- -----------------------------------------------------
-- 3) DENUNCIAS DE PRUEBA VIA sp_registrar_denuncia
--    Cada caso: (etiqueta, canton_id, distrito_id, area esperada por codigo)
--    Las ubicaciones se leen de ubicacion_area para no depender de ids fijos.
-- -----------------------------------------------------
DECLARE
  v_ok    NUMBER := 0;
  v_fallo NUMBER := 0;
  v_canton NUMBER; v_distrito NUMBER;

  PROCEDURE registrar_caso (
    p_etiqueta     IN VARCHAR2,
    p_canton_id    IN NUMBER,
    p_distrito_id  IN NUMBER,
    p_area_esperada IN VARCHAR2      -- codigo_area; NULL = se espera error -20008
  ) IS
    v_json   CLOB;
    v_id     NUMBER;
    v_cons   VARCHAR2(60);
    v_codigo_area area.codigo_area%TYPE;
    v_codigo_seg VARCHAR2(20) := 'H8' || TO_CHAR(DBMS_RANDOM.VALUE(100000, 999999), 'FM999999') || SUBSTR(p_etiqueta, 1, 6);
  BEGIN
    v_json := '{"hecho":{"denunciado_otra_institucion":"N","denunciado_previamente_minsalud":"N",'
           || '"nombre_establecimiento":"HU008-' || p_etiqueta || '",'
           || '"descripcion_hecho":"Denuncia de prueba HU-008 (' || p_etiqueta || ')"},'
           || '"ubicacion":{"canton_id":' || p_canton_id || ','
           || '"distrito_id":' || NVL(TO_CHAR(p_distrito_id), 'null') || ','
           || '"direccion_exacta":"Direccion de prueba"},'
           || '"privacidad":{"es_anonima":"S"},'
           || '"productos":[{"tipo_producto_id":1,"nombre_producto_texto":"Producto prueba",'
           || '"descripcion_producto":"Descripcion de prueba","motivos":[8]}]}';

    BEGIN
      sp_registrar_denuncia(v_json, SUBSTR(v_codigo_seg, 1, 20), v_id, v_cons);
      SELECT a.codigo_area INTO v_codigo_area
        FROM denuncia d JOIN area a ON a.id_area = d.area_actual_id
       WHERE d.id_denuncia = v_id;

      IF v_codigo_area = p_area_esperada THEN
        v_ok := v_ok + 1;
        DBMS_OUTPUT.PUT_LINE('[OK]    ' || RPAD(p_etiqueta, 24) || ' -> ' || v_codigo_area || '  ' || v_cons);
      ELSE
        v_fallo := v_fallo + 1;
        DBMS_OUTPUT.PUT_LINE('[FALLO] ' || RPAD(p_etiqueta, 24) || ' -> ' || v_codigo_area
                             || ' (esperada ' || NVL(p_area_esperada, 'ERROR -20008') || ')');
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        IF SQLCODE = -20008 AND p_area_esperada IS NULL THEN
          v_ok := v_ok + 1;
          DBMS_OUTPUT.PUT_LINE('[OK]    ' || RPAD(p_etiqueta, 24) || ' -> sin area (error -20008 esperado)');
        ELSE
          v_fallo := v_fallo + 1;
          DBMS_OUTPUT.PUT_LINE('[FALLO] ' || RPAD(p_etiqueta, 24) || ' -> ' || SQLERRM);
        END IF;
    END;
  END registrar_caso;

  -- primer (canton, distrito) mapeado a un area y el n-esimo distrito de ese area
  PROCEDURE caso_area (p_etiqueta VARCHAR2, p_codigo VARCHAR2, p_n NUMBER, p_copias NUMBER DEFAULT 1) IS
    v_canton NUMBER; v_distrito NUMBER;
  BEGIN
    SELECT canton_id, distrito_id INTO v_canton, v_distrito FROM (
      SELECT ua.canton_id, ua.distrito_id, ROW_NUMBER() OVER (ORDER BY ua.id_ubicacion_area) rn
        FROM ubicacion_area ua JOIN area a ON a.id_area = ua.area_id
       WHERE a.codigo_area = p_codigo
    ) WHERE rn = p_n;
    FOR i IN 1 .. p_copias LOOP
      registrar_caso(p_etiqueta || '-' || i, v_canton, v_distrito, p_codigo);
    END LOOP;
  END caso_area;

BEGIN
  DBMS_OUTPUT.PUT_LINE('=== 3) Denuncias de prueba ===');

  -- ABAN: 7 denuncias en varios distritos (las que se veran en la bandeja de HU-012)
  caso_area('ABAN-d1', 'ABAN', 1, 3);
  caso_area('ABAN-d2', 'ABAN', 2, 2);
  caso_area('ABAN-d3', 'ABAN', 3, 1);
  caso_area('ABAN-d4', 'ABAN', 4, 1);

  -- ACOS: 2 denuncias (deben quedar en OTRA bandeja)
  caso_area('ACOS-d1', 'ACOS', 1, 1);
  caso_area('ACOS-d2', 'ACOS', 2, 1);

  -- Distrito de un canton cuyo mapeo se comparte entre cantones (Aserri -> Acosta)
  SELECT canton_id, distrito_id INTO v_canton, v_distrito FROM (
    SELECT ua.canton_id, ua.distrito_id FROM ubicacion_area ua JOIN area a ON a.id_area = ua.area_id
     WHERE a.codigo_area = 'ACOS' ORDER BY ua.id_ubicacion_area
  ) WHERE ROWNUM = 1;
  registrar_caso('ACOS-cross-canton', v_canton, v_distrito, 'ACOS');

  -- Sin distrito (canton sin division): el mapeo del CSV tiene distrito NULL
  FOR r IN (SELECT ua.canton_id, a.codigo_area FROM ubicacion_area ua JOIN area a ON a.id_area = ua.area_id
             WHERE ua.distrito_id IS NULL) LOOP
    registrar_caso('SINDISTRITO-' || r.codigo_area, r.canton_id, NULL, r.codigo_area);
  END LOOP;

  -- Negativo: un distrito real que NO esta en ubicacion_area debe dar error -20008
  BEGIN
    SELECT d.canton_id, d.id_distrito INTO v_canton, v_distrito FROM distrito d
     WHERE NOT EXISTS (SELECT 1 FROM ubicacion_area ua WHERE ua.distrito_id = d.id_distrito)
       AND NOT EXISTS (SELECT 1 FROM ubicacion_area ua WHERE ua.canton_id = d.canton_id AND ua.distrito_id IS NULL)
       AND ROWNUM = 1;
    registrar_caso('SIN-AREA', v_canton, v_distrito, NULL);
  EXCEPTION WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('[INFO]  Todos los distritos tienen area; no hay caso negativo.');
  END;

  -- Las denuncias se re-etiquetan al area de prueba: no hace falta, quedan en ABAN.
  DBMS_OUTPUT.PUT_LINE('Resultado casos: ' || v_ok || ' OK, ' || v_fallo || ' FALLO');
END;
/


-- #####################################################################
-- Flujo completo en 4 areas: denuncias y asignaciones
-- Origen: 16_prueba_hu008_asignacion_areas.sql (seccion 3b)
-- #####################################################################
-- -----------------------------------------------------
-- 3b) FLUJO COMPLETO EN 4 AREAS
--     5 denuncias en ACOS, LIMO y SRAM con datos realistas,
--     registradas con sp_registrar_denuncia. En cada area el jefe
--     asigna 3 (sp_asignar_funcionario_encargado: historial,
--     bitacora y notificacion) y 2 quedan por asignar. En ABAN se
--     asigna 1 de las pendientes a Alejandra Castro (100); las de
--     Valeria Mora (303) se asignan en el script 18, que la crea.
-- -----------------------------------------------------
DECLARE
  v_id   NUMBER;
  v_aban NUMBER;

  FUNCTION registrar (p_area VARCHAR2, p_n NUMBER, p_establecimiento VARCHAR2, p_descripcion VARCHAR2,
                      p_tipo NUMBER, p_producto VARCHAR2, p_desc_producto VARCHAR2, p_motivo NUMBER)
    RETURN NUMBER IS
    v_canton NUMBER; v_distrito NUMBER; v_total NUMBER;
    v_json CLOB; v_id_den NUMBER; v_cons VARCHAR2(60);
  BEGIN
    SELECT COUNT(*) INTO v_total
      FROM ubicacion_area ua JOIN area a ON a.id_area = ua.area_id WHERE a.codigo_area = p_area;
    SELECT canton_id, distrito_id INTO v_canton, v_distrito FROM (
      SELECT ua.canton_id, ua.distrito_id, ROW_NUMBER() OVER (ORDER BY ua.id_ubicacion_area) rn
        FROM ubicacion_area ua JOIN area a ON a.id_area = ua.area_id WHERE a.codigo_area = p_area
    ) WHERE rn = MOD(p_n - 1, v_total) + 1;

    v_json := '{"hecho":{"denunciado_otra_institucion":"N","denunciado_previamente_minsalud":"N",'
           || '"nombre_establecimiento":"' || p_establecimiento || '",'
           || '"descripcion_hecho":"' || p_descripcion || '"},'
           || '"ubicacion":{"canton_id":' || v_canton || ','
           || '"distrito_id":' || NVL(TO_CHAR(v_distrito), 'null') || ','
           || '"direccion_exacta":"' || p_establecimiento || ', frente al parque central"},'
           || '"privacidad":{"es_anonima":"S"},'
           || '"productos":[{"tipo_producto_id":' || p_tipo || ','
           || '"nombre_producto_texto":"' || p_producto || '",'
           || '"descripcion_producto":"' || p_desc_producto || '",'
           || '"motivos":[' || p_motivo || ']}]}';

    sp_registrar_denuncia(v_json, 'PRB-' || p_area || '-' || LPAD(p_n, 2, '0'), v_id_den, v_cons);
    DBMS_OUTPUT.PUT_LINE('[OK]    ' || v_cons || '  ' || p_establecimiento);
    RETURN v_id_den;
  END registrar;

  PROCEDURE asignar (p_denuncia NUMBER, p_encargado NUMBER, p_jefe NUMBER) IS
  BEGIN
    sp_asignar_funcionario_encargado(p_denuncia, p_encargado, p_jefe, 'Asignacion inicial (datos de prueba)');
  END asignar;
BEGIN
  DBMS_OUTPUT.PUT_LINE('=== 3b) Flujo completo en 4 areas ===');

  -- ACOS (jefas 9110 y 9112)
  v_id := registrar('ACOS', 1, 'Farmacia La Esperanza',
          UNISTR('Se venden tabletas de acetaminof\00E9n con fecha de vencimiento expirada.'),
          5, UNISTR('Acetaminof\00E9n 500 mg'), 'Caja de 100 tabletas', 8);
  asignar(v_id, 9113, 9112);
  v_id := registrar('ACOS', 2, 'Supermercado El Ahorro',
          'La leche en polvo no indica el lote ni la fecha de vencimiento en la etiqueta.',
          1, 'Leche en polvo entera', 'Bolsa de 900 g', 3);
  asignar(v_id, 9111, 9112);
  v_id := registrar('ACOS', 3, 'Tienda Belleza Natural',
          UNISTR('Crema aclaradora sin registro sanitario y con ingredientes no declarados.'),
          3, 'Crema aclaradora facial', 'Frasco de 50 ml', 11);
  asignar(v_id, 9114, 9110);
  v_id := registrar('ACOS', 4, 'Pagina de Facebook Suplementos CR',
          UNISTR('Se publicita un suplemento que promete curar la diabetes en dos semanas.'),
          10, 'Quemador de grasa natural', 'Frasco de 60 capsulas', 5);
  v_id := registrar('ACOS', 5, UNISTR('Pulper\00EDa Don Chepe'),
          'Embutidos con olor y color anormales a la venta en refrigeradora sin temperatura.',
          1, 'Salchichon', 'Paquete de 500 g', 2);

  -- LIMO (jefe 9120)
  v_id := registrar('LIMO', 1, 'Farmacia del Puerto',
          UNISTR('Se sospecha que la amoxicilina vendida es falsificada: el empaque difiere del original.'),
          5, 'Amoxicilina 500 mg', 'Caja de 21 capsulas', 4);
  asignar(v_id, 9122, 9120);
  v_id := registrar('LIMO', 2, UNISTR('Mercado Municipal de Lim\00F3n'),
          UNISTR('Latas de at\00FAn abombadas y vencidas en el puesto de abarrotes.'),
          1, UNISTR('At\00FAn en agua'), 'Lata de 140 g', 8);
  asignar(v_id, 9123, 9120);
  v_id := registrar('LIMO', 3, UNISTR('Bazar Caribe\00F1o'),
          UNISTR('Un tinte para cabello provoc\00F3 quemaduras en el cuero cabelludo de una clienta.'),
          3, 'Tinte para cabello', 'Caja con dos tubos', 10);
  asignar(v_id, 9121, 9120);
  v_id := registrar('LIMO', 4, 'Tienda de vapeo Nube Azul',
          UNISTR('L\00EDquidos para vapeo sin registro sanitario ni advertencias en espa\00F1ol.'),
          12, 'Liquido para vapeo sabor menta', 'Frasco de 30 ml', 11);
  v_id := registrar('LIMO', 5, 'Agroveterinaria El Campo',
          UNISTR('Insecticida dom\00E9stico reenvasado en botellas de refresco sin etiqueta.'),
          6, UNISTR('Insecticida dom\00E9stico'), 'Botella de 600 ml', 3);

  -- SRAM (jefes 9130 y 9131)
  v_id := registrar('SRAM', 1, UNISTR('Farmacia San Ram\00F3n'),
          UNISTR('Un ni\00F1o present\00F3 intoxicaci\00F3n tras tomar un jarabe para la tos.'),
          5, 'Jarabe para la tos infantil', 'Frasco de 120 ml', 6);
  asignar(v_id, 9132, 9130);
  v_id := registrar('SRAM', 2, UNISTR('Panader\00EDa La Espiga'),
          'Pan dulce con presencia de moho a la venta en vitrina.',
          1, 'Pan dulce', 'Bolsa de 6 unidades', 2);
  asignar(v_id, 9133, 9131);
  v_id := registrar('SRAM', 3, 'Naturista Vida Sana',
          UNISTR('T\00E9 adelgazante que se promociona para bajar 10 kilos en una semana.'),
          8, UNISTR('T\00E9 adelgazante'), 'Caja de 30 sobres', 5);
  asignar(v_id, 9132, 9130);
  v_id := registrar('SRAM', 4, 'Estudio de tatuajes Arte Vivo',
          'Tintas para tatuaje importadas sin registro ni etiquetado.',
          11, 'Tinta negra para tatuaje', 'Frasco de 30 ml', 7);
  v_id := registrar('SRAM', 5, 'Distribuidora La Central',
          UNISTR('Toallas h\00FAmedas con olor qu\00EDmico fuerte; se sospecha adulteraci\00F3n.'),
          7, UNISTR('Toallas h\00FAmedas'), 'Paquete de 80 unidades', 1);

  -- ABAN: la primera pendiente a Alejandra Castro (100), asignada por el jefe 1.
  SELECT MIN(d.id_denuncia) INTO v_aban
    FROM denuncia d JOIN area a ON a.id_area = d.area_actual_id
   WHERE a.codigo_area = 'ABAN' AND d.estado = 'PENDIENTE_ASIGNACION' AND d.funcionario_asignado_id IS NULL;
  IF v_aban IS NOT NULL THEN
    asignar(v_aban, 100, 1);
  END IF;
END;
/


-- #####################################################################
-- HU-001: usuarios y claves de prueba para todos los funcionarios
-- Origen: 18_seed_usuarios_temporales.sql
-- #####################################################################
-- =====================================================
-- 18_seed_usuarios_temporales.sql
-- HU-001 - Iniciar sesion al sistema del SDPIS.
--
-- Siembra credenciales LOCALES de prueba en usuario_temporal
-- (tabla del script 17) para TODOS los funcionarios de prueba,
-- de modo que se pueda recorrer el flujo completo con cualquier
-- rol en 4 areas (ABAN, ACOS, LIMO, SRAM) y la UVC.
--
-- Crea ademas sus propios funcionarios 301-303 (si no existen):
--   110110110  superusuario  301  UVC
--   220220220  jefe_area     302  ABAN (Abangares)
--   330330330  validador     303  ABAN (Abangares)
-- Los demas funcionarios vienen de 06, 08, 13, 14 y 16.
--
-- USUARIO: cedula (o correo). CLAVE DE TODOS: ClavePrueba2026!
-- Cedula = rol + area + secuencia, repetido 3 veces:
--   rol: 1 superusuario, 2 jefe de area, 3 funcionario
--   area: 1 UVC, 2 ABAN, 3 ACOS, 4 LIMO, 5 SRAM
--   p. ej. 232232232 = jefe (2) de ACOS (3), el segundo (2).
-- Todo usuario tiene nombre y dos apellidos; funcionario.nombre
-- coincide con lo que muestra la tarjeta del portal.
--
-- SOLO hashes BCrypt (costo 12) de claves falsas de prueba.
--
-- Al final asigna 2 denuncias pendientes de ABAN a Valeria Mora
-- (303), para que la usuaria de prueba tenga trabajo en Bitacora y
-- Criticidad (solo si aun no tiene ninguna).
--
-- Reejecutable: MERGE idempotente por identificacion.
-- OJO: despues de este script NO re-ejecute solos 06, 08, 13 ni 16
-- (borran funcionarios que ahora tienen usuario: falla por FK).
-- Use 00_reset_local.sql y recargue todo en orden.
-- Requisitos previos: 05 (areas), 06, 08, 13, 14 (especialidad y
-- permite_asignar), 16 (funcionarios por area) y 17.
-- =====================================================

DECLARE
  -- Hash BCrypt (costo 12) de ClavePrueba2026!
  c_hash CONSTANT VARCHAR2(60) := '$2a$12$mmH0bXzHcCBwtsW./TXlc.Dzb6VpjT8tQWHoxUt4Y/FLv.MwCpaBW';

  PROCEDURE asegurar_funcionario (
    p_id          NUMBER,
    p_nombre      VARCHAR2,
    p_rol         VARCHAR2,
    p_correo      VARCHAR2,
    p_codigo_area VARCHAR2,
    p_permite     CHAR
  ) IS
    v_area_id area.id_area%TYPE;
  BEGIN
    BEGIN
      SELECT id_area INTO v_area_id FROM area WHERE codigo_area = p_codigo_area;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20950,
          'No existe el area ' || p_codigo_area || '. Ejecute antes los scripts 05 y 13.');
    END;

    MERGE INTO funcionario f
    USING (SELECT p_id AS id_funcionario FROM dual) s
       ON (f.id_funcionario = s.id_funcionario)
    WHEN MATCHED THEN
      UPDATE SET f.nombre = p_nombre, f.rol = p_rol, f.correo = p_correo,
                 f.area_id = v_area_id, f.activo = 'S', f.permite_asignar = p_permite
    WHEN NOT MATCHED THEN
      INSERT (id_funcionario, nombre, rol, correo, area_id, activo, permite_asignar)
      VALUES (p_id, p_nombre, p_rol, p_correo, v_area_id, 'S', p_permite);
  END asegurar_funcionario;

  -- Credencial del funcionario con ese correo (debe existir). El nombre
  -- que se guarda en funcionario es nombre + apellido1 + apellido2,
  -- igual al que muestra la tarjeta del portal.
  PROCEDURE asegurar_usuario (
    p_identificacion VARCHAR2,
    p_nombre         VARCHAR2,
    p_apellido1      VARCHAR2,
    p_apellido2      VARCHAR2,
    p_correo         VARCHAR2
  ) IS
    v_id  funcionario.id_funcionario%TYPE;
    v_rol funcionario.rol%TYPE;
  BEGIN
    IF TRIM(p_nombre) IS NULL OR LENGTH(TRIM(p_apellido1)) < 2 OR LENGTH(TRIM(p_apellido2)) < 2 THEN
      RAISE_APPLICATION_ERROR(-20951,
        'El usuario ' || p_identificacion || ' debe tener nombre y dos apellidos completos.');
    END IF;

    BEGIN
      SELECT id_funcionario, rol INTO v_id, v_rol
        FROM funcionario WHERE LOWER(correo) = LOWER(p_correo);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20952,
          'No existe el funcionario ' || p_correo || '. Revise el orden de los scripts.');
    END;

    UPDATE funcionario
       SET nombre = p_nombre || ' ' || p_apellido1 || ' ' || p_apellido2
     WHERE id_funcionario = v_id;

    MERGE INTO usuario_temporal t
    USING (SELECT p_identificacion AS identificacion FROM dual) s
       ON (t.identificacion = s.identificacion)
    WHEN MATCHED THEN
      UPDATE SET t.funcionario_id = v_id,
                 t.nombre = p_nombre,
                 t.apellido1 = p_apellido1,
                 t.apellido2 = p_apellido2,
                 t.correo_institucional = LOWER(p_correo),
                 t.rol = v_rol,
                 t.clave_hash = c_hash,
                 t.activo = 'S',
                 t.fecha_modificacion = SYSDATE
    WHEN NOT MATCHED THEN
      INSERT (funcionario_id, identificacion, nombre, apellido1, apellido2,
              correo_institucional, rol, clave_hash, activo)
      VALUES (v_id, p_identificacion, p_nombre, p_apellido1, p_apellido2,
              LOWER(p_correo), v_rol, c_hash, 'S');
  END asegurar_usuario;
BEGIN
  -- ---------- Funcionarios propios de este script ----------
  asegurar_funcionario(301, UNISTR('Danny Quir\00F3s Solano'), 'superusuario', 'superusuario@sdpis.go.cr', 'UVC',  'S');
  asegurar_funcionario(302, 'Rosa Uribe Vargas',              'jefe_area',    'jefe.area@sdpis.go.cr',    'ABAN', 'S');
  asegurar_funcionario(303, 'Valeria Mora Chaves',            'validador',    'valeria.mora@sdpis.go.cr', 'ABAN', 'N');

  -- ---------- UVC ----------
  asegurar_usuario('110110110', 'Danny', UNISTR('Quir\00F3s'), 'Solano', 'superusuario@sdpis.go.cr');
  asegurar_usuario('111111111', 'Danny', UNISTR('Calder\00F3n'), 'Vega', 'daniel.q@sdpis.go.cr');
  asegurar_usuario('311311311', UNISTR('M\00F3nica'), 'Fallas', 'Rojas', 'monica.f@sdpis.go.cr');

  -- ---------- ABAN (Abangares) ----------
  asegurar_usuario('220220220', 'Rosa', 'Uribe', 'Vargas', 'jefe.area@sdpis.go.cr');
  asegurar_usuario('221221221', 'Rodrigo', 'Alvarado', UNISTR('Sol\00EDs'), 'rodrigo.alvarado@sdpis.go.cr');
  asegurar_usuario('330330330', 'Valeria', 'Mora', 'Chaves', 'valeria.mora@sdpis.go.cr');
  asegurar_usuario('321321321', 'Alejandra', 'Castro', 'Rojas', 'alejandra.c@sdpis.go.cr');
  asegurar_usuario('322322322', 'Ariana', UNISTR('Le\00F3n'), 'Mora', 'ariana.l@sdpis.go.cr');
  asegurar_usuario('323323323', 'Arisai', 'Barrantes', UNISTR('Sol\00EDs'), 'arisai.b@sdpis.go.cr');
  asegurar_usuario('324324324', 'Daniel', 'Quesada', 'Castro', 'danny.c@sdpis.go.cr');
