-- El IDENTITY de funcionario no debe generar ids ya usados a mano
-- (200, 201, 301-303): se lleva al siguiente libre, minimo 500, sin
-- tocar el rango 9100-9199 que maneja el script 16.
DECLARE
  v_siguiente NUMBER;
BEGIN
  SELECT GREATEST(500, NVL(MAX(id_funcionario), 0) + 1) INTO v_siguiente
    FROM funcionario WHERE id_funcionario < 9000;
  EXECUTE IMMEDIATE 'ALTER TABLE funcionario MODIFY id_funcionario '
                 || 'GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_siguiente || ')';
END;
/

-- Trabajo para Valeria Mora (303): 2 denuncias pendientes de ABAN,
-- asignadas por la jefa 302. Solo si aun no tiene ninguna.
DECLARE
  TYPE t_ids IS TABLE OF NUMBER;
  v_ids      t_ids;
  v_asignadas NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_asignadas FROM denuncia WHERE funcionario_asignado_id = 303;
  IF v_asignadas > 0 THEN
    RETURN;
  END IF;

  SELECT id_denuncia BULK COLLECT INTO v_ids FROM (
    SELECT d.id_denuncia
      FROM denuncia d JOIN area a ON a.id_area = d.area_actual_id
     WHERE a.codigo_area = 'ABAN'
       AND d.estado = 'PENDIENTE_ASIGNACION'
       AND d.funcionario_asignado_id IS NULL
     ORDER BY d.id_denuncia
  ) WHERE ROWNUM <= 2;

  -- sp_asignar_funcionario_encargado hace COMMIT; por eso se leen los ids antes.
  FOR i IN 1 .. v_ids.COUNT LOOP
    sp_asignar_funcionario_encargado(v_ids(i), 303, 302, 'Asignacion inicial (datos de prueba)');
  END LOOP;
END;
/

-- #####################################################################
-- Plan de usabilidad: datos realistas para las 2 denuncias de
-- Valeria Mora (303), que se usan en las tareas #05, #06, #07, #09
-- y #12. Sin esto se verian como "HU008-ABAN-d1-x / Producto prueba".
--   1.a (ABAN-2026-000005): crema blanqueadora -> #05, #06 y #12
--   2.a (ABAN-2026-000006): yogur vencido      -> #07 y #09
-- Se ubican por funcionario asignado, no por consecutivo.
-- #####################################################################
DECLARE
  TYPE t_ids IS TABLE OF NUMBER;
  v_ids t_ids;

  PROCEDURE ajustar (p_denuncia NUMBER, p_establecimiento VARCHAR2, p_descripcion VARCHAR2,
                     p_direccion VARCHAR2, p_tipo NUMBER, p_producto VARCHAR2,
                     p_desc_producto VARCHAR2, p_marca VARCHAR2, p_presentacion VARCHAR2,
                     p_motivo1 NUMBER, p_motivo2 NUMBER DEFAULT NULL) IS
    v_det detalle_producto.id_detalle_producto%TYPE;
  BEGIN
    UPDATE denuncia_hecho
       SET nombre_establecimiento = p_establecimiento,
           descripcion_hecho      = p_descripcion
     WHERE denuncia_id = p_denuncia;

    UPDATE denuncia_ubicacion
       SET direccion_exacta = p_direccion
     WHERE denuncia_id = p_denuncia;

    SELECT id_detalle_producto INTO v_det
      FROM detalle_producto
     WHERE denuncia_id = p_denuncia AND ROWNUM = 1;

    UPDATE detalle_producto
       SET tipo_producto_id      = p_tipo,
           nombre_producto_texto = p_producto,
           descripcion_producto  = p_desc_producto,
           marca_ingresada       = p_marca
     WHERE id_detalle_producto = v_det;

    UPDATE detalle_producto_compra
       SET presentacion = p_presentacion
     WHERE id_detalle_producto = v_det;

    DELETE FROM detalle_producto_motivo WHERE id_detalle_producto = v_det;
    INSERT INTO detalle_producto_motivo (id_detalle_producto, id_motivo) VALUES (v_det, p_motivo1);
    IF p_motivo2 IS NOT NULL THEN
      INSERT INTO detalle_producto_motivo (id_detalle_producto, id_motivo) VALUES (v_det, p_motivo2);
    END IF;
  END ajustar;
BEGIN
  SELECT id_denuncia BULK COLLECT INTO v_ids
    FROM denuncia
   WHERE funcionario_asignado_id = 303
   ORDER BY id_denuncia;

  IF v_ids.COUNT < 2 THEN
    RAISE_APPLICATION_ERROR(-20960, 'Valeria Mora (303) deberia tener 2 denuncias asignadas.');
  END IF;

  -- ABAN-2026-000005: Cosmetico (3), motivos Seguridad (10) y Sin Registro Sanitario (11)
  ajustar(v_ids(1),
          'Bazar y Variedades El Minero',
          UNISTR('Se vende una crema blanqueadora sin registro sanitario. Varias clientas reportan ardor y manchas rojas en la cara despu\00E9s de usarla.'),
          'Las Juntas de Abangares, 100 m sur del parque central',
          3, 'Crema blanqueadora Piel de Seda',
          UNISTR('Crema para aclarar manchas de la piel, envase sin etiqueta en espa\00F1ol'),
          'Piel de Seda', 'Frasco de 60 g',
          10, 11);

  -- ABAN-2026-000006: Alimento (1), motivo Producto vencido (8)
  ajustar(v_ids(2),
          UNISTR('Minis\00FAper Los Mangos'),
          UNISTR('En la refrigeradora del minis\00FAper se venden botellas de yogur bebible con la fecha de vencimiento expirada hace m\00E1s de dos semanas.'),
          'Las Juntas de Abangares, 200 m este de la escuela',
          1, 'Yogur bebible sabor fresa',
          'Bebida de yogur en botella plastica',
          UNISTR('L\00E1cteos del Valle'), 'Botella de 200 ml',
          8);

  COMMIT;
END;
/
-- #####################################################################
-- HU-015: cupo de jefes segun los datos de prueba
-- Origen: 21_roles_permisos.sql (seccion 4)
-- #####################################################################
-- =====================================================
-- 4) AJUSTE DE DATOS DE PRUEBA: cupo de jefes
--    Los scripts de prueba (08, 13, 16, 18) crean varios jefes en la
--    misma area (ABAN llega a 4). El cupo se valida al crear/editar,
--    no corrige datos existentes; para que la pantalla no muestre
--    "4/2" y se pueda probar el limite, se sube el cupo de esas areas
--    a la cantidad de jefes activos que ya tienen (nunca lo baja).
--    Los superusuarios en renuncia no cuentan para el cupo.
-- =====================================================
UPDATE area a
   SET a.max_jefes = (
         SELECT COUNT(*) FROM funcionario f
          WHERE f.area_id = a.id_area AND f.rol = 'jefe_area' AND f.activo = 'S'
            AND NOT EXISTS (SELECT 1 FROM funcionario_permiso fp
                             WHERE fp.funcionario_id = f.id_funcionario
                               AND fp.codigo_permiso = 'RENUNCIA_SUPERUSUARIO'))
 WHERE a.max_jefes < (
         SELECT COUNT(*) FROM funcionario f
          WHERE f.area_id = a.id_area AND f.rol = 'jefe_area' AND f.activo = 'S'
            AND NOT EXISTS (SELECT 1 FROM funcionario_permiso fp
                             WHERE fp.funcionario_id = f.id_funcionario
                               AND fp.codigo_permiso = 'RENUNCIA_SUPERUSUARIO'));

COMMIT;
